INSERT INTO membrane_retrofits(assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES
('A095-R1','R095-01','CN0084','precious_metal_2024_generation','screening',1,'贵金属回收与水回用','先调查三股水及既有金属回收，按组分评价膜浓缩','unknown','不能增加贵金属损失或不合规危废','S095-02','INFERRED，未证实接入关系','流量、金属、pH、盐、有机物、末端工艺','分股采样、金属衡算、膜相容性及处置审查','现行金属回收优化',NULL,NULL,NULL,NULL,NULL,NULL,'缺实际数据','2026-11-28'),
('A095-R2','R095-02','CN0127','historical_zero_discharge_demo','screening',1,'比较膜预浓缩与历史MVR负荷','在预处理后按盐度、硬度、COD评价膜预浓缩，比较MVR及母液干化','conditional','浓液结垢与重金属合规，实际回收率、全成本','S095-01及既有W06S01扩建设计','INFERRED；49元/t仅MVR段指定价格核算，不可直接折算项目收益','现行进水量、膜型号、实际电汽药耗、浓液去向','对照2026采购验收、实测与全费用衡算','优化既有调质与蒸发',NULL,NULL,NULL,NULL,NULL,NULL,'未取得六维实际输入','2026-11-28');
INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N095-01','CN0127','S095-01','历史工程技术经济','序号4 p4截图','2020投用；预处理浊度35NTU、含固率<0.1%、泥饼含水77.23%；调质生化出水COD447、氨氮38.9mg/L、硬度<50mg/L（CaCO3）；MVR直接费用49元/t按电0.6元/kWh、蒸汽130元/t、药剂均价7000元/t。2021–2023累计减少废水排放13768t、冷凝回用节约自来水13080t、间接效益16.57万元；每年可减少污水排放5570t、COD2.5t为成果估计。减排非进站量，不能以49乘减排量估算总成本。','WEB_COMPANY','截图及正文核对；非独立运行台账','2026-11-28'),
('N095-02','CN0084','S095-02','贵金属生产产污与危废','表1–3 p3–4截图','企业申报贵金属催化剂年产80t、贵金属活性炭危废年产生5t，批次法脱盐水介质，W6夹套、W1母液及滤饼冲洗、W2真空干燥水。压滤废渣与不合格品为拟转移处置物；半固体废物组成活性炭<28%、水<70%、钯铂钌<2%，不是废水浓度。具体装置厂址及污水后端待核。','WEB_PRIMARY','政府公开企业申请截图','2026-11-28'),
('N095-03','CN0270','S095-03','第三阶段验收公示','2025-04-10公示正文','第三阶段3000t/a催化剂项目及4067.9m²新建厂房，公示至05-07；未得报告原件，不能确认实际产量、污水监测、验收结论；10000t/a再生与危废许可不可重复加总。','WEB_SECONDARY','转载正文','2026-11-28'),
('N095-04','CN0253','S041-05','共享站历史设施','2023报告p29–30','报告列现有高浓水芬顿混凝后进入生化，事故池有效容积960及1200m³；共享设施非IPN线专属，既有处理流程已录不重复；p29截图超时，正文可读。','WEB_PRIMARY','原报告正文；局部截图受阻','2026-11-28');
